int main(int argc,char** argv){try{
 check(argc==5,"Usage: diplomacy_response_boundary_test CATALOG REQUEST RESULT BANK_DIRECTORY");const auto catalog=read(argv[1]),request=read(argv[2]);check(text(request,"scenario_id")=="diploreply::scenario.qingchuan_diplomatic_response","Normal explicit response author scene required");std::filesystem::create_directories(argv[4]);const std::filesystem::path banks=argv[4];auto session=create_resident_replay_session();need(session->initialize_native(catalog,request),"Install actual response scene");
 for(Integer n=0;n<4;++n)advance(*session);const auto funded=export_state(*session);check(boundary::get_int(field(field(funded,"wallets"),"society::wallet.city_steward"),"balance","wallet")==12,"Original salary did not supply real private travel money");const auto task=accept_self_mission(*session);travel_to_recipient(*session);meet_recipient(*session);submit_action(*session,diplomatic_action(*session,"envoy_deliver"));save_bank(*session,banks,"active");check(snapshot(*session).diplomacy.replies.empty(),"Reply occurred before real delivery");late_response_rollback(*session,catalog,banks);advance(*session);
 const auto state=snapshot(*session);check(state.diplomacy.presentations.size()==1&&state.diplomacy.replies.size()==1,"Director did not adopt exactly one explicit reply");const auto& reply=state.diplomacy.replies.rows().front().second;check(reply.authority.actor_id=="society::actor.sect_steward"&&reply.decision==DiplomaticReplyKind::accept,"Reply did not come from the real current authorized NPC");const auto* offer=state.diplomacy.offers.find(reply.offer_id);check(offer&&offer->status==DiplomaticOfferStatus::accepted_pending_ratification,"NPC acceptance activated a treaty");const auto* responsibility=state.envoy.envoy_contracts.find(task);check(responsibility&&responsibility->completion&&responsibility->completion->result==EnvoyTaskResult::completed,"NPC reply damaged completed envoy responsibility");const auto exported=export_state(*session);const auto& plan=field(field(field(exported,"director"),"plans"),"society::actor.sect_steward");check(text(plan,"template_id")=="diplomatic_response"&&text(plan,"goal_ref")==offer->id,"Reply did not use the original Director plan and goal");save_bank(*session,banks,"replied");const auto checkpoint=need(session->checkpoint(),"Response checkpoint");auto cold=create_resident_replay_session();need(cold->initialize_checkpoint(catalog,checkpoint),"Cold restore actual NPC reply");check(checkpoint==need(cold->checkpoint(),"Re-export reply bank"),"Cold reply changed original bytes");query(*cold,"journal_text");diplomatic_page(*cold);check(checkpoint==need(cold->checkpoint(),"After reply pure views"),"Reply pages changed cold world");trace.push_back(boundary::obj({{"actual_reply_page",diplomatic_page(*session)},{"actual_director_plan",plan},{"treaty_effect",V{"none; pending ratification"}}}));save(argv[3],true);std::cout<<"DIPLOMATIC_RESPONSE_BOUNDARY "<<checks<<" checks 0 failures; one real NPC reply, cold read and late whole-World rollback\n";return 0;
}catch(const std::exception& error){if(argc==5)try{save(argv[3],false,error.what());}catch(...){}std::cerr<<"DIPLOMATIC_RESPONSE_BOUNDARY FAIL "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}
